import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import { WordpressIncidentsApi, WordpressIncident } from '@imunify360-api/wordpress-incidents';
import { Observable, map, catchError, of } from 'rxjs';
import { RequestsState } from 'app/services/requests-state';
import { UntranslatableString } from 'app/utils/translate/translate.service';
import { WordPressPluginAPI, IUserDomain } from '@imunify360-api/wordpress-plugin';

@Injectable({ providedIn: 'root' })
export class WordPressPluginService {
    _listIncidents = this.xhr.rx(WordpressIncidentsApi.listIncidents);
    listIncidents = this.xhr.wrap(this._listIncidents, WordpressIncident);
    wpSites = this.xhr.rx(WordPressPluginAPI.listSites, false, false);

    constructor(
        private xhr: XHR,
        private requestsState: RequestsState,
    ) {}

    getDomainsList(): Observable<IUserDomain[]> {
        const requestFn = () => {
            return this.wpSites().pipe(
                catchError(() => of({ data: { items: [] } }))
            );
        }
        return this.requestsState.makeCachedRequest(requestFn, 'userDomains')
            .pipe(map(res => res?.data?.items));
    }

    getDomainsListForTableWidget(): Observable<{ [key: string]: string }> {
        return this.getDomainsList().pipe(map((domains: IUserDomain[] ) => {
            const domainsMap = domains.reduce((acc, curr) => {
                acc[curr.domain] = UntranslatableString.for(curr.domain);
                return acc;
            }, {});

            const allTranslateKey = 'utils.table.widgets.content.by_domain.values.all';
            return { 'all': allTranslateKey, ...domainsMap };
        }));
    }
}
