import { Component, forwardRef, OnDestroy, OnInit } from '@angular/core';
import {
    ControlValueAccessor,
    FormArray,
    FormBuilder,
    FormControl,
    FormGroup,
    NG_VALIDATORS,
    NG_VALUE_ACCESSOR,
    ValidationErrors,
    Validator,
    Validators,
} from '@angular/forms';
import { Subject, takeUntil } from 'rxjs';

@Component({
    selector: 'i360-port-limits-editor',
    templateUrl: './port-limits-editor.component.html',
    styleUrls: [`./port-limits-editor.component.scss`],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => PortLimitsEditorComponent),
            multi: true,
        },
        {
            provide: NG_VALIDATORS,
            useExisting: forwardRef(() => PortLimitsEditorComponent),
            multi: true,
        },
    ],
})
export class PortLimitsEditorComponent implements OnInit, OnDestroy, ControlValueAccessor, Validator {

    form: FormGroup;
    submitted = false;
    private destroyed$ = new Subject<void>();
    private onChange: (value: Record<string, number>) => void = () => {};
    private onTouched: () => void = () => {};

    constructor(private fb: FormBuilder) {
        this.form = this.fb.group({
            pairs: this.fb.array([]),
        });
    }

    get pairs(): FormArray {
        return this.form.get('pairs') as FormArray;
    }

    get isValid(): boolean {
        return this.form.valid;
    }

    markSubmitted(): void {
        this.submitted = true;
    }

    resetSubmitted(): void {
        this.submitted = false;
    }

    ngOnInit(): void {
        setTimeout(()=> {
             if (!this.pairs.value?.length) {
                this.addPair();
            }
        })
        this.form.valueChanges
            .pipe(takeUntil(this.destroyed$))
            .subscribe(() => {
                this.emitValue();
                this.onTouched();
            });
    }

    ngOnDestroy(): void {
        this.destroyed$.next();
        this.destroyed$.complete();
    }

    // ControlValueAccessor
    writeValue(value: Record<string, number>): void {
        this.pairs.clear();
        const entries = Object.entries(value || {});
        entries.forEach(([port, limit]) => {
            this.pairs.push(this.createPairGroup(port, limit));
        });
        // If empty, don't add default pair - user should click "Add" button
    }

    registerOnChange(fn: (value: Record<string, number>) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    // Validator - return null, validation errors shown inline per field
    validate(): ValidationErrors | null {
        return null;
    }

    // Actions
    addPair(): void {
        this.pairs.push(this.createPairGroup('', 250));
    }

    removePair(index: number): void {
        this.pairs.removeAt(index);
    }

    getError(control: any): string | null {
        if (!control?.invalid) return null;
        if (control.hasError('required')) return 'validators.fieldRequired';
        if (control.hasError('pattern')) return 'validators.pattern';
        if (control.hasError('min')) return 'validators.min';
        if (control.hasError('max')) return 'validators.max';
        return null;
    }

    getErrorParams(control: any): any {
        if (control?.hasError('min')) return { min: 100 };
        if (control?.hasError('max')) return { max: 10000 };
        return {};
    }

    private createPairGroup(port: string, limit: number): FormGroup {
        const portPattern = /^(?:[1-9]\d{0,3}|[1-5]\d{4}|6[0-4]\d{3}|65[0-4]\d{2}|655[0-2]\d|6553[0-5])(?:-(?:[1-9]\d{0,3}|[1-5]\d{4}|6[0-4]\d{3}|65[0-4]\d{2}|655[0-2]\d|6553[0-5]))?$/;
        return this.fb.group({
            port: new FormControl(port, [
                Validators.required,
                Validators.pattern(portPattern),
            ]),
            limit: new FormControl(limit, [
                Validators.required,
                Validators.min(100),
                Validators.max(10000),
                Validators.pattern(/^\d+$/),
            ]),
        });
    }

    private emitValue(): void {
        const dict: Record<string, number> = {};
        for (const ctrl of this.pairs.controls) {
            const grp = ctrl as FormGroup;
            // Only emit valid pairs
            if (grp.valid) {
                const port = (grp.get('port')?.value || '').toString().trim();
                const limit = Number(grp.get('limit')?.value);
                if (port && !isNaN(limit)) {
                    dict[port] = limit;
                }
            }
        }
        this.onChange(dict);
    }
}

