import { Component, ElementRef, Input, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import * as Diff2Html from 'diff2html';
import * as Sentry from '@sentry/angular';


@Component({
    selector: 'i360-diff-viewer',
    template: `
        <div [innerHTML]="diffHtml" class="i360-diff-viewer-container"></div>
    `,
    styleUrls: ['./diff-viewer.component.scss']
})
export class DiffViewerComponent implements OnInit {
    @Input() decodedDiff = '';
    @Input() fileName = '';

    diffHtml: SafeHtml | undefined;
    @ViewChild('diffContainer', {static: true}) diffContainer!: ElementRef;

    constructor(private sanitizer: DomSanitizer) {
    }

    ngOnInit(): void {
        try {
            let decodedDiff = atob(this.decodedDiff);
            if (!decodedDiff.startsWith('diff --git')) {
                decodedDiff = `diff --git a${this.fileName} a${this.fileName}\n${decodedDiff}`;
            }

            const diffJson = Diff2Html.parse(decodedDiff);
            const outputHtml = Diff2Html.html(diffJson, {
                outputFormat: 'line-by-line',
                drawFileList: false,
                matching: 'lines',

            });
            const cleanedHtml = outputHtml.replace(/<label class="d2h-file-collapse">.*?<\/label>/gs, '');

            this.diffHtml = this.sanitizer.bypassSecurityTrustHtml(cleanedHtml);
        } catch (e) {
            Sentry.captureException(new Error('An error occurred while preparing html diff: ' + JSON.stringify(e)));
        }
    }
}
