import { Directive, ElementRef, HostBinding, HostListener } from '@angular/core';

// Mostly for cPanel user-side <= v66
@Directive({
  selector: '[i360-dropdown]',
})
export class I360DropdownDirective {
    @HostBinding('class.show') isOpen: boolean = false;

    constructor(private element: ElementRef) {}

    @HostListener('click') open() {
        let el = this.element.nativeElement.querySelector('.dropdown-menu');
        if (el) {
            const classList = el.classList;
            if (!this.isOpen) {
                classList.add('show');
            } else {
                classList.remove('show');
            }
        }

        this.isOpen = !this.isOpen;
    }

    @HostListener('document:click', ['$event.target']) close (target) {
        if (!this.element.nativeElement.contains(target)) {
            this.isOpen = false;
            const dropdownMenu = this.element.nativeElement.querySelector('.dropdown-menu')
            if (dropdownMenu) {
                dropdownMenu.classList.remove('show');
            }
        }
    }
}
