import { Component, Inject, ViewChild } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { ModalEntry } from 'app/utils/modals/entry';
import { PortLimitsEditorComponent } from '../port-limits-editor/port-limits-editor.component';
import { SettingsService } from 'app/services/settings';
import { firstValueFrom } from 'rxjs';
import { AbstractControl } from '@angular/forms';
import { NotificationsService } from 'app/services/notifications';

export interface PortLimitsDialogData {
    portLimits: Record<string, number>;
    configGroup: 'DOS' | 'ENHANCED_DOS';
    formControl: AbstractControl;
}

export interface PortLimitsDialogResult {
    portLimits: Record<string, number>;
}

@Component({
    selector: 'i360-port-limits-dialog',
    templateUrl: './port-limits-dialog.component.html',
    styleUrls: ['./port-limits-dialog.component.scss'],
})
export class PortLimitsDialogComponent extends ModalEntry<PortLimitsDialogData, PortLimitsDialogResult> {
    @ViewChild(PortLimitsEditorComponent) editor: PortLimitsEditorComponent;

    portLimits: Record<string, number>;
    saving = false;

    constructor(
        private dialogRef: MatDialogRef<PortLimitsDialogComponent>,
        private settingsService: SettingsService,
        private notifications: NotificationsService,
        @Inject(MAT_DIALOG_DATA) public data: PortLimitsDialogData,
    ) {
        super();
        this.portLimits = { ...data.portLimits };
    }

    onPortLimitsChange(value: Record<string, number>): void {
        this.portLimits = value;
    }

    async apply(): Promise<void> {
        this.editor.markSubmitted();

        if (!this.editor.isValid) {
            return;
        }

        this.saving = true;
        try {
            await firstValueFrom(this.settingsService.saveSettings({
                [this.data.configGroup]: {
                    port_limits: this.portLimits,
                },
            }));
            this.notifications.success('settings.successSaveMessage');
            this.dialogRef.close({ portLimits: this.portLimits });
        } finally {
            this.saving = false;
        }
    }

    cancel(): void {
        this.dialogRef.close();
    }
}
