import { Injectable } from '@angular/core';
import { HttpErrorResponse, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { NEVER, Observable, throwError, catchError } from 'rxjs';

import { NotificationsService } from 'app/services/notifications';
import { Panel } from 'app/utils/panel';
import { baseEndpoint } from '@imunify360-api/server';

declare const IS_WORDPRESS_PLUGIN: boolean;

@Injectable()
export class SessionExpiredInterceptor implements HttpInterceptor {
    constructor(
        private notifications: NotificationsService,
        public panel: Panel,

    ) {}

    intercept(req: HttpRequest<any>, next: HttpHandler): Observable<any> {
        return next.handle(req).pipe(
            catchError((err: HttpErrorResponse) => {
                // Skip server API errors, because they don't need any auth
                if (err.url?.includes(baseEndpoint)) {
                    return throwError(() => err);
                }

                if (!(err.error instanceof Error) && this.sessionExpired(err)) {
                    this.throwUnauthorizedError(err.status);
                    return NEVER;
                } else if (!(err.error instanceof Error) &&
                    (this.panel.isCpanel && err.error.text
                        && err.error.text.search('<title>WHM Login</title>'))) {
                    window.location.reload();
                }
                throw err;
            }),
        );
    }

    public sessionExpired(response: HttpErrorResponse): boolean {
        if (typeof IS_WORDPRESS_PLUGIN === 'boolean' &&
            IS_WORDPRESS_PLUGIN && response.status == 0 ) {
            return false;
        }
        // Check if session expired for cPanel
        // cPanel also can return status 0 for Chrome
        if ([401, 0].includes(response.status)) {
            return true;
        }
        // Check if session expired for Plesk
        if (this.panel.isPlesk && response.error &&
            (/login\.php/.test(response.error.text) || response.url?.includes('login_up.php'))) {
            return true;
        }
        // Check if session expired for DirectAdmin
        return (response.headers && response.headers.get('X-DirectAdmin') === 'unauthorized');
    }

    async throwUnauthorizedError(status: number = 401) {
        if (typeof IS_WORDPRESS_PLUGIN === 'boolean' && IS_WORDPRESS_PLUGIN) {
            try {
                if (window.parent && window.parent !== window) {
                    window.parent.postMessage({ type: 'imunify-session-expired' }, '*');
                }
            } catch (e) {
                // fallback: do nothing here to avoid iframe reload loop
            }
            return;
        }

        let message = status
            ? 'interceptors.sessionExpired.sessionExpired'
            : 'interceptors.sessionExpired.connectionReset';
        this.notifications.error(message, 'interceptors.sessionExpired.internalError');
        setTimeout(() => {
            window.location.reload();
        }, 10000);
    }
}
