import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import {
    AnalystCleanupAPI,
    IAnalystCleanupRequestParams,
    RequestedCleanupItem,
} from '@imunify360-api/analyst-cleanup';
import { Observable, of, map, switchMap } from 'rxjs';
import { AppState } from 'app/core/app.service';
import { Package } from '@imunify360-api/license';
import { AuthState } from 'app/services/auth-state';


@Injectable({ providedIn: 'root' })
export class AnalystCleanupService {
    request = this.xhr.rx(AnalystCleanupAPI.request);
    private _getRequests = this.xhr.rx(AnalystCleanupAPI.getRequests);
    getRequests = this.xhr.wrap(this._getRequests, RequestedCleanupItem);
    isAllowedAssistedCleanup = this.xhr.rx(AnalystCleanupAPI.isAllowed);

    constructor(
        private xhr: XHR,
        private appState: AppState,
        private authState: AuthState,
        ) {
    }

    createRequest(params: IAnalystCleanupRequestParams) {
        return this.request(params);
    }

    isAllowed(): Observable<boolean> {
        const isAllowed = this.appState.isAllowedAssistedCleanup$.getValue();
        if (typeof isAllowed === 'boolean') {
            return of(isAllowed);
        }

        return this.isAllowedAssistedCleanup().pipe(
            map(response => {
                const isAllowed = Boolean(response?.data?.items?.is_allowed);
                this.appState.isAllowedAssistedCleanup$.next(isAllowed);
                return isAllowed;
            }),
        );
    }

    checkIsAllowedAssistedCleanup(): Observable<boolean> {
        if (IMUNIFY_PACKAGE !== Package.imunify360) {
            return of(false);
        }

        return this.authState.isAdmin
            .pipe(
                switchMap(isAdmin => {
                    return isAdmin ? this.isAllowed() : of(false);
                }),
            );
    }
}
