import { Injectable } from '@angular/core';
import { Panel } from 'app/utils/panel';
import { AuthState } from 'app/services/auth-state';
import { Observable, of, combineLatest, map } from 'rxjs';
import { AdminConfigType } from 'app/utils/config/admin-config';

@Injectable()
export class PleskUtilsService {
    constructor(
        private panel: Panel,
        private authState: AuthState,
    ) {
    }

    isUsingPleskServicePlan(config$: Observable<AdminConfigType>): Observable<boolean> {
        if (!this.panel.isPlesk) {
            return of(false);
        }

        return combineLatest([this.authState.isClient, config$])
            .pipe(map(([isClient, config]) => {
                return !!(isClient && config.PERMISSIONS?.use_plesk_service_plan);
            }));
    }

    isUserCleanupAllowed(): boolean {
        if (typeof i360PleskSettings !== 'undefined') {
            return !!i360PleskSettings.userCleanupAllowed;
        }

        return false;
    }

    isUserScanAllowed(): boolean {
        if (typeof i360PleskSettings !== 'undefined') {
            return !!i360PleskSettings.userScanAllowed;
        }

        return false;
    }
}
